import torch


def run_correctness(inp):
    inp.copy_(torch.atanh(inp.float()).to(inp.dtype))
    return inp


def run(inp):
    return inp.atanh_()


def gen_inputs(ctx, device):
    # Source distribution: torch.rand(shape, dtype) * 1.8 - 0.9 -> uniform in [-0.9, 0.9),
    # kept strictly inside the atanh domain (-1, 1). Candidate dtype is preserved.
    dtype = getattr(torch, ctx["inp__dtype"])
    shape = tuple(ctx["inp__shape"])
    inp = torch.rand(shape, dtype=dtype, device=device) * 1.8 - 0.9
    return {"inp": inp}
